const r = await api.get('/contacts', {});
// assume response is array of contacts
const contacts = r;
const totalContacts = contacts.length;
// extract distinct company names
const companies = new Set();
for (const c of contacts) {
  if (c.company) companies.add(c.company);
}
return { totalContacts, companyCount: companies.size };

const r = await api.get('/contacts', {});
// r may be {items: [...], count: number}
if (!Array.isArray(r)) {
  if (Array.isArray(r.items)) {
    const contacts = r.items;
    const totalContacts = contacts.length;
    const companies = new Set();
    for (const c of contacts) {
      if (c.company) companies.add(c.company);
    }
    return { totalContacts, companyCount: companies.size };
  }
}
// fallback assume r is array
const contacts = r;
const totalContacts = contacts.length;
const companies = new Set();
for (const c of contacts) {
  if (c.company) companies.add(c.company);
}
return { totalContacts, companyCount: companies.size };

